// 10 CLM claims designed to separate semantic from lexical ranking on
// the query "transparency and legitimacy" (Michael's test case).
const CLAIMS = [
  // semantic hits: about institutional transparency, none contain the query words
  "Public trust declines when institutions hide how decisions are made",
  "Open deliberation records make citizens more likely to accept unfavorable rulings",
  "Communities comply with rules more readily when they can see who decided and why",
  "Closed-door budget negotiations increase suspicion of corruption",
  "Publishing meeting minutes reduces disputes over council decisions",
  // lexical traps: contain the query words, unrelated meaning
  "Transparency of window glass determines solar panel output",
  "Legitimacy of a mathematical proof rests on its weakest lemma",
  // mid-relevance: same domain, different aspect
  "Participatory budgeting raises civic engagement in mid-sized cities",
  "Frequent leadership turnover erodes institutional memory in regulatory agencies",
  // distractor
  "Sourdough starters ferment faster at higher ambient humidity",
];

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamAlphaAPI?.data?.page?.create));
  },

  async run({ page }) {
    const created = await page.evaluate(async (claims) => {
      const api = window.roamAlphaAPI;
      const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
      const out = [];
      for (const content of claims) {
        const title = `[[CLM]] - ${content}`;
        const existing = api.q(
          "[:find ?u . :in $ ?t :where [?e :node/title ?t] [?e :block/uid ?u]]",
          title,
        );
        if (existing) {
          out.push({ title, uid: existing, status: "already existed" });
          continue;
        }
        const uid = api.util.generateUID();
        await api.data.page.create({ page: { title, uid } });
        await sleep(120);
        const check = api.q(
          "[:find ?u . :in $ ?t :where [?e :node/title ?t] [?e :block/uid ?u]]",
          title,
        );
        out.push({ title, uid: check || null, status: check ? "created" : "FAILED" });
      }
      return out;
    }, CLAIMS);

    // measure our own ranking for the same query Michael used
    const rank = async (query) => {
      await page.keyboard.press("Escape");
      await page.keyboard.press("Meta+p");
      await page.waitForTimeout(600);
      await page.keyboard.type("Open Node Search", { delay: 25 });
      await page.waitForTimeout(800);
      await page.keyboard.press("Enter");
      const input = page.locator('input[placeholder="Search discourse nodes..."]');
      await input.waitFor({ timeout: 20000 });
      await input.click();
      await input.type(query, { delay: 40 });
      await page.waitForTimeout(2500);
      const rows = await page.evaluate(() => {
        const box = document.querySelector('[aria-label="Search results"][role="listbox"]');
        if (!box) return null;
        return Array.from(box.querySelectorAll('[role="option"]')).map((r) =>
          (r.textContent || "").trim(),
        );
      });
      await page.keyboard.press("Escape");
      await page.waitForTimeout(400);
      return rows;
    };

    const semanticEnabled = await page.evaluate(() =>
      window.roamAlphaAPI.data.semanticSearchEnabled(),
    );

    return {
      semanticEnabled,
      created,
      ranking: {
        "transparency and legitimacy": await rank("transparency and legitimacy"),
        transparency: await rank("transparency"),
        trust: await rank("trust"),
      },
    };
  },
};
