        pageUid = api.util.generateUID();
        await api.data.page.create({ page: { title: pageTitle, uid: pageUid } });
        await sleep(200);
        pageUid = uidForTitle(pageTitle);
        pageStatus = pageUid ? "created" : "FAILED";
      }
      if (!pageUid) return { pageStatus: "FAILED", pageTitle };

      // existing top-level block strings, so re-runs do not duplicate
      const existing = new Set(
        (api.q(
