          pageUid,
        ) || []).map(([s]) => s),
      );

      const added = [];
      let order = existing.size;
      for (const [heading, claims] of groups) {
        const headingStr = `**${heading}**`;
        if (!existing.has(headingStr)) {
          const hUid = api.util.generateUID();
          await api.data.block.create({
            location: { "parent-uid": pageUid, order: order++ },
            block: { uid: hUid, string: headingStr },
          });
          await sleep(110);
          added.push(headingStr);
          for (let i = 0; i < claims.length; i++) {
            const link = `[[[[CLM]] - ${claims[i]}]]`;
            await api.data.block.create({
              location: { "parent-uid": hUid, order: i },
              block: { uid: api.util.generateUID(), string: link },
            });
