          if (p && p[":block/uid"] && p[":node/title"]) {
            titleByUid[p[":block/uid"]] = p[":node/title"];
          }
        });
        const rows = pages.map((h) => ({
          uid: h.uid,
          score: h.score,
          title: titleByUid[h.uid] || null,
        }));
