// Shared quiz behaviour. Markup contract:
//   <div class="quiz" data-answer="1">
//     <p class="quiz__q">...</p>
//     <div class="quiz__opts"><button class="quiz__opt">...</button>...</div>
//     <p class="quiz__fb">feedback shown after answering</p>
//   </div>
// Immediate feedback, one attempt, running score in [data-score].
document.addEventListener("DOMContentLoaded", () => {
  const quizzes = Array.from(document.querySelectorAll(".quiz"));
  const scoreEl = document.querySelector("[data-score]");
  let answered = 0;
  let correct = 0;

  const renderScore = () => {
    if (!scoreEl) return;
    scoreEl.textContent = `${correct} of ${answered} correct (${quizzes.length} total)`;
  };

  quizzes.forEach((quiz) => {
    const answer = Number(quiz.dataset.answer);
    const opts = Array.from(quiz.querySelectorAll(".quiz__opt"));
    const fb = quiz.querySelector(".quiz__fb");

    opts.forEach((opt, i) => {
      opt.addEventListener("click", () => {
        if (quiz.dataset.done) return;
        quiz.dataset.done = "true";
        answered += 1;
        if (i === answer) correct += 1;
        opts.forEach((o, j) => {
          o.disabled = true;
          if (j === answer) o.classList.add("quiz__opt--right");
          else if (j === i) o.classList.add("quiz__opt--wrong");
        });
        if (fb) fb.classList.add("quiz__fb--shown");
        renderScore();
      });
    });
  });

  renderScore();
});
